loadWindow:
const values = { restoreSession: bootstrap.restoreSession != null ? String(bootstrap.restoreSession) : undefined, supportsSettings: bootstrap.supportsSettings != null ? String(bootstrap.supportsSettings) : undefined, initialWorkspacePath: bootstrap.initialWorkspacePath, initialWorkspacePurpose: bootstrap.initialWorkspacePurpose, unavailableWorkspacePath: bootstrap.unavailableWorkspacePath, windowKind: bootstrap.windowKind, locale: bootstrap.locale };
const query = Object.fromEntries(Object.entries(values).filter(([,value]) => value != null)) as Record<string,string>;
const partial = getMainLaunchPartialMarks();
query[LAUNCH_MARKS_QUERY_KEY] = serializeLaunchMarks({...partial, loadUrl: Date.now()});
if (!app.isPackaged && process.env['ELECTRON_RENDERER_URL']) {
 const url = new URL(process.env['ELECTRON_RENDERER_URL']);
 for (const [key,value] of Object.entries(query)) url.searchParams.set(key,value);
 return win.loadURL(url.toString());
}
return win.loadFile(join(import.meta.dirname, '../renderer/index.html'), {query});

spawnHostProcess:
const hostId = randomUUID();
const binary = resolveBundledAgentBinaryPath();
const execArgv = [...(RUNTIME_KNORVIA_DEBUG ? [`--inspect-brk=${RUNTIME_KNORVIA_DEBUG}`] : []), '--no-warnings'];
const child = electronUtilityProcess.fork(hostModulePath, [], {serviceName: formatKnorviaHostProcessName(label), execArgv, env: {...buildHostProcessEnv(dependencies.hostProcessLocalEnv), ...buildHostE2ECoverageEnv(), KNORVIA_PROCESS_LABEL: label, ...(process.platform === 'darwin' ? {KNORVIA_CUA_LAUNCHER_PID: String(process.pid)} : {}), ...(dependencies.desktopContextPromptEnabled ? {[KNORVIA_DESKTOP_CONTEXT_PROMPT_ENABLED_ENV]: dependencies.desktopContextPromptEnabled() ? '1' : '0'} : {})}});
dependencies.logger.info(`[spawnHostProcess] forked host process for (${label}), pid=${child.pid}`);
dependencies.logger.info(`[spawnHostProcess] host module path: ${hostModulePath}`);
dependencies.logger.info(`[spawnHostProcess] Knorvia agent binary path: ${binary ?? '<not found>'}`);
const logs = createHostLogRelay(label, dependencies.logger as Parameters<typeof createHostLogRelay>[1]);
child.stderr?.on('data', (data: Buffer) => logs.onStderr(data.toString()));
child.stdout?.on('data', (data: Buffer) => logs.onStdout(data.toString()));
const database = bindDatabaseStartupRelay(win, child, hostId);
child.on('message', (message: unknown) => dispatchHostMessage(win, child, label, dependencies, database, logs, message));
const hasRealtime = options?.taskRealtime != null;
const init = {...initMessage, databaseStartupId: database.startupId, ...(hasRealtime ? {hostId, deliveryKind: options?.taskRealtime?.deliveryKind} : {})};
if (options?.attachInitialServicePort === false) child.postMessage(init);
else {
 const {port1, port2} = new MessageChannelMain();
 child.postMessage(init, [port2]);
 if (options?.onPortReady) options.onPortReady(port1);
 else win.webContents.postMessage(options?.internalChannel ?? InternalChannels.ServicePort, options?.internalChannel === InternalChannels.ScopedServicePort ? options.internalPayload ?? null : {databaseStartupId: database.startupId}, [port1]);
}
const windowId = win.webContents.id;
const broadcast = options?.registerBroadcast ?? true;
if (broadcast) dependencies.broadcastHub.register(windowId,child);
if (hasRealtime && dependencies.taskRealtimeBus && options?.taskRealtime) {
 dependencies.taskRealtimeBus.registerHost({hostId, windowId: win.id, child, workspaceKeys: options.taskRealtime.workspaceKeys, deliveryKind: options.taskRealtime.deliveryKind});
 options.taskRealtime.onHostId?.(hostId);
}
registerHostProcess(label,child);
child.on('exit', (code) => {
 lifecycle.exited.add(child);
 dependencies.onCuaOperationStateSourceExited?.(child);
 logs.flushRawLogs();
 dependencies.logger.info(`[spawnHostProcess] host process (${label}) exited with code ${code}`);
 dependencies.hostRunningTaskCountMap.delete(child);
 if (broadcast) dependencies.broadcastHub.unregister(windowId);
 unregisterHostProcess(label);
 for (const [key,value] of dependencies.windowHostProcessMap) { if (value === child) {dependencies.windowHostProcessMap.delete(key);break;} }
});
return child;
